// Per-product marketing copy + spec bullets, keyed by `${brand}|${model}` (the
// exact model string from products.json). Rendered on the product detail page
// and fed into Product structured data for SEO. Pure static content — no DB, no
// secrets — so it ships in the public repo and lands on the next deploy with
// zero schema migration or reseed.
//
// SOURCING RULE: specs are grounded in the EXACT model's official
// reyee.ruijie.com page, or in the authoritative `name` string from
// products.json (the distributor's own headline spec). Reyee has many
// near-identical suffixes (e.g. RAP2260 vs 2260E/2260G/2260H) that are DIFFERENT
// products — numbers are never copied from a sibling model. Universal-platform
// statements (Ruijie Cloud / Reyee app management, Reyee Mesh on mesh-capable
// gear) are documented line-wide features. If a number couldn't be confirmed for
// the exact model, it is left out rather than guessed.

export interface ProductDoc {
  /** one-line hook shown under the product name */
  tagline: string;
  /** 1–2 short Thai paragraphs of marketing copy */
  body: string;
  /** spec bullets with Thai labels (do not restate the name field) */
  specs: string[];
}

